themeCSS:
.nodeLabel, .node .label, .node .label text, .node .label tspan { font-size:14px; font-weight:500; }
.node rect, .node polygon, .node circle, .node ellipse, .node path { fill:#252b26; stroke:#404842; }
.cluster rect { fill:#222523; stroke:#404842; }
.node rect, .cluster rect { rx:8px; ry:8px; stroke-width:1px; }
.cluster-label text, .cluster-label span { fill:#b3bab4; color:#b3bab4; }
.flowchart-link { stroke-width:1px; stroke-linecap:round; stroke-linejoin:round; }
